93	// startServer 在 dataDir 上启动真实服务子进程（--port 0 自动选端口），返回基地址。
94	function startServer(t, dataDir) {
95	  const proc = spawn(
96	    serverBin,
97	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
98	    { stdio: ['ignore', 'pipe', 'inherit'] },
99	  );
100	  t.after(() => { proc.kill('SIGKILL'); });
101	  return new Promise((resolve, reject) => {
102	    let buf = '';
103	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
104	    proc.stdout.on('data', (chunk) => {
105	      buf += chunk.toString();
106	      const m = buf.match(/listening on (http:\/\/\S+)/);
107	      if (m) {
108	        clearTimeout(timer);
109	        resolve(m[1]);
110	      }
111	    });
112	    proc.on('exit', (code) => {
113	      clearTimeout(timer);
114	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
115	    });
116	  });
117	}
