221	// installCreateGate 打开请求拦截：每次 POST /api/rooms 都先挂起，由测试
222	// 显式 release 决定放行到真实服务还是直接构造响应（如服务拒绝）；其余请求
223	// （页面、GET 列表）照常放行。挂起期间正是“创建结果返回前”的观察窗口。
224	function installCreateGate(page) {
225	  const posts = [];
226	  page.on('request', (req) => {
227	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
228	      const entry = { body: req.postData() };
229	      posts.push(entry);
230	      entry.whenReleased = new Promise((resolve) => {
231	        entry.release = (how) => { entry.how = how || { type: 'continue' }; resolve(); };
232	      });
233	      entry.whenReleased.then(() => {
234	        if (entry.how.type === 'respond') req.respond(entry.how.params);
235	        else req.continue();
236	      });
237	    } else {
238	      req.continue();
239	    }
240	  });
241	  return {
242	    posts,
243	    async waitFor(count) {
244	      const deadline = Date.now() + 10000;
245	      while (posts.length < count) {
246	        if (Date.now() > deadline) {
247	          throw new Error(`等待第 ${count} 次创建请求超时（实际 ${posts.length} 次）`);
248	        }
249	        await sleep(10);
250	      }
251	    },
252	  };
253	}
