639	// 联动一致性（五子棋 → 飞行棋但未选人数）：保留下来的规则为飞行棋时人数
640	// 必须停留在未选择状态而不是沿用五子棋的 2；立即提交按现有规则拦截，选好
641	// 人数后再次提交才创建。
642	test('等待期间五子棋切飞行棋且未选人数：保留状态与规则相符，缺人数被拦截后补齐再提交', { timeout: 60000 }, async (t) => {
643	  const { page, baseURL } = await setupPage(t);
644	  const gate = installCreateGate(page);
645	  await page.setRequestInterception(true);
646	  const createdPromise = nextPostResponse(page);
647	
648	  await page.type('#name', '联动保留的房间');
649	  await chooseGame(page, 'gomoku');
650	  await setTurnSeconds(page, '30');
651	  await page.click('#submit');
652	  await gate.waitFor(1);
653	
654	  // 等待期间切到飞行棋：人数沿用五子棋的 2（现有联动保留合法人数），再手动
655	  // 改选占位空项模拟“尚未选完整”，并改时间；名称保持不动。
656	  await chooseGame(page, 'ludo');
657	  await page.select('#capacity', '');
658	  await setTurnSeconds(page, '77');
659	
660	  gate.posts[0].release();
661	  const created = await createdPromise;
662	  assert.equal(created.status, 201);
663	  assert.equal(created.body.game, 'gomoku', '本次创建仍使用提交时的五子棋');
664	  assert.equal(created.body.capacity, 2);
665	  assert.equal(created.body.turnSeconds, 30);
666	
667	  await waitForMessageKind(page, 'ok');
668	  // 保留状态与规则相符：飞行棋已选、人数未选（可选择），不自动补成 2。
669	  // 等列表刷新完成（按钮随之恢复）后再比对完整表单状态。
670	  await waitForRowCount(page, 3);
671	  assert.deepEqual(await readFormState(page), {
672	    name: '联动保留的房间',
673	    game: 'ludo',
674	    capacity: '',
675	    capacityDisabled: false,
676	    turnSeconds: '77',
677	    submitDisabled: false,
678	  }, '保留的人数选择状态必须与飞行棋规则相符，未选完整不自动补齐');
679	
680	  // 立即提交按现有规则拦截（缺人数），不发请求，内容保留。
681	  await page.click('#submit');
682	  await waitForMessageKind(page, 'error');
683	  assert.equal((await readMessage(page)).text, CAPACITY_REQUIRED_TEXT);
684	  await sleep(200);
685	  assert.equal(gate.posts.length, 1, '缺人数时不得发出创建请求');
686	
687	  // 选好人数后再次提交：以保留的飞行棋/3 人/77 秒创建。
688	  const secondPromise = nextPostResponse(page);
689	  await page.select('#capacity', '3');
690	  await page.click('#submit');
691	  await gate.waitFor(2);
692	  assert.deepEqual(JSON.parse(gate.posts[1].body), {
693	    name: '联动保留的房间',
694	    game: 'ludo',
695	    capacity: 3,
696	    turnSeconds: 77,
697	  });
698	  gate.posts[1].release();
699	  const second = await secondPromise;
700	  assert.equal(second.status, 201);
701	  assert.equal(second.body.game, 'ludo');
702	  assert.equal(second.body.capacity, 3);
703	  assert.equal(second.body.turnSeconds, 77);
704	  await waitForRowCount(page, 4);
705	  assert.deepEqual(await readFormState(page), RESET_FORM);
