708	// 联动一致性（飞行棋/4 人 → 五子棋）：等待期间切到五子棋后人数自动固定为
709	// 2，保留状态即五子棋/2 人，再次提交直接以该配置创建。
710	test('等待期间飞行棋切五子棋：人数自动固定 2 人并保留，再次提交以五子棋 2 人创建', { timeout: 60000 }, async (t) => {
711	  const { page, baseURL } = await setupPage(t);
712	  const gate = installCreateGate(page);
713	  await page.setRequestInterception(true);
714	  const createdPromise = nextPostResponse(page);
715	
716	  await page.type('#name', '切换规则的房间');
717	  await chooseGame(page, 'ludo');
718	  await page.select('#capacity', '4');
719	  await setTurnSeconds(page, '60');
720	  await page.click('#submit');
721	  await gate.waitFor(1);
722	  assert.deepEqual(JSON.parse(gate.posts[0].body), {
723	    name: '切换规则的房间',
724	    game: 'ludo',
725	    capacity: 4,
726	    turnSeconds: 60,
727	  });
728	
729	  // 等待期间改规则为五子棋：人数自动固定 2；名称、时间不动。
730	  await chooseGame(page, 'gomoku');
731	
732	  gate.posts[0].release();
733	  const created = await createdPromise;
734	  assert.equal(created.status, 201);
735	  assert.equal(created.body.game, 'ludo', '本次创建仍使用提交时的飞行棋');
736	  assert.equal(created.body.capacity, 4);
737	
738	  await waitForMessageKind(page, 'ok');
739	  const msg = await readMessage(page);
740	  assert.equal(msg.text, SUCCESS_PREFIX + created.body.id + RETAIN_SUFFIX);
741	  // 等列表刷新完成后按钮恢复可用，再比对完整表单状态。
742	  await waitForRowCount(page, 3);
743	  assert.deepEqual(await readFormState(page), {
744	    name: '切换规则的房间',
745	    game: 'gomoku',
746	    capacity: '2',
747	    capacityDisabled: false,
748	    turnSeconds: '60',
749	    submitDisabled: false,
750	  }, '切到五子棋后应保留自动固定的 2 人状态');
751	
752	  // 再次提交直接以五子棋/2 人创建。
753	  const secondPromise = nextPostResponse(page);
754	  await page.click('#submit');
755	  await gate.waitFor(2);
756	  assert.deepEqual(JSON.parse(gate.posts[1].body), {
757	    name: '切换规则的房间',
758	    game: 'gomoku',
759	    capacity: 2,
760	    turnSeconds: 60,
761	  });
762	  gate.posts[1].release();
763	  const second = await secondPromise;
764	  assert.equal(second.body.game, 'gomoku');
765	  assert.equal(second.body.capacity, 2);
766	  await waitForRowCount(page, 4);
767	  assert.deepEqual(await readFormState(page), RESET_FORM);
768	  const serverRooms = await readServerRooms(baseURL);
769	  assert.equal(serverRooms[2].game, 'ludo');
770	  assert.equal(serverRooms[3].game, 'gomoku');
771	});
772	
773	// 创建被服务拒绝：显示服务给出的原因、不出现成功编号、列表保持原样；等待
774	// 期间的最新四项仍保留，不因失败回退到提交时内容；修正后再次提交成功。
775	test('创建被服务拒绝：显示服务原因、无编号、列表不变，等待期间最新填写保留，修正后再提交成功', { timeout: 60000 }, async (t) => {
776	  const { page, baseURL } = await setupPage(t);
777	  const initialRows = await readRows(page);
778	  assertSeedRows(initialRows);
779	  const seedRooms = await readServerRooms(baseURL);
780	
781	  const gate = installCreateGate(page);
782	  await page.setRequestInterception(true);
783	  const rejectedPromise = nextPostResponse(page);
784	
785	  // 提交时：五子棋配置。
786	  await page.type('#name', '  被拒绝的房间  ');
787	  await chooseGame(page, 'gomoku');
788	  await setTurnSeconds(page, '30');
789	  await page.click('#submit');
790	  await gate.waitFor(1);
791	
792	  // 等待期间改成飞行棋/4 人/90 秒（最新填写）。
793	  await editToLudo4(page);
794	
795	  // 服务拒绝本次创建并给出原因（真实服务不会收到这次请求）。
796	  const REASON = '服务端拒绝：本场赛事的公开房间数量已达上限';
797	  gate.posts[0].release({
798	    type: 'respond',
799	    params: {
800	      status: 400,
801	      contentType: 'application/json; charset=utf-8',
802	      body: JSON.stringify({ error: REASON }),
803	    },
804	  });
805	  const rejected = await rejectedPromise;
806	  assert.equal(rejected.status, 400);
807	
808	  // 显示服务给出的具体原因，不出现成功编号或成功文案。
809	  await waitForMessageKind(page, 'error');
810	  const msg = await readMessage(page);
811	  assert.equal(msg.text, REASON, '应原样显示服务给出的拒绝原因');
812	  assert.ok(!msg.text.includes(SUCCESS_PREFIX), '被拒绝时不应出现成功编号');
813	  assert.ok(!msg.text.includes('已创建'), '被拒绝时不应出现成功文案');
814	
815	  // 等待期间的最新四项原样保留，不回退到提交时的五子棋配置；按钮恢复可用。
816	  assert.deepEqual(await readFormState(page), {
817	    name: '等待中改成飞行棋',
818	    game: 'ludo',
819	    capacity: '4',
820	    capacityDisabled: false,
821	    turnSeconds: '90',
822	    submitDisabled: false,
823	  }, '被拒绝后应保留等待期间的最新填写，不回退到提交时内容');
824	
825	  // 已有列表与服务端记录保持原样，不新增房间。
826	  assert.deepEqual(await readRows(page), initialRows, '被拒绝时列表应保持原样');
827	  assert.deepEqual(await readServerRooms(baseURL), seedRooms, '服务端不应新增房间记录');
828	
829	  // 以保留的最新填写再次提交：放行到真实服务，按当前配置创建成功。
830	  const secondPromise = nextPostResponse(page);
831	  await page.click('#submit');
832	  await gate.waitFor(2);
833	  assert.equal(gate.posts.length, 2, '处理完成后应能再次提交');
834	  assert.deepEqual(JSON.parse(gate.posts[1].body), {
835	    name: '等待中改成飞行棋',
836	    game: 'ludo',
837	    capacity: 4,
838	    turnSeconds: 90,
839	  }, '再次提交应使用保留的最新填写');
840	  gate.posts[1].release();
841	  const second = await secondPromise;
842	  assert.equal(second.status, 201);
843	  assert.equal(second.body.game, 'ludo');
844	  assert.equal(second.body.capacity, 4);
845	
846	  // 拒绝原因被成功结果替换，表单复位，列表追加一间。
847	  await waitForMessageKind(page, 'ok');
848	  const okMsg = await readMessage(page);
849	  assert.equal(okMsg.text, SUCCESS_PREFIX + second.body.id, '成功后应替换为普通成功提示');
850	  assert.ok(!okMsg.text.includes(REASON), '成功后不应残留拒绝原因');
851	  await waitForRowCount(page, 3);
852	  assert.deepEqual(await readFormState(page), RESET_FORM);
853	  const serverRooms = await readServerRooms(baseURL);
854	  assert.equal(serverRooms.length, 3);
855	  assert.deepEqual(serverRooms.slice(0, 2), seedRooms);
856	  assert.equal(serverRooms[2].id, second.body.id);
857	});
858	
859	// 按钮禁用窗口覆盖“提交等待 + 随后的列表刷新”：POST 与创建后的列表查询都
860	// 挂起时按钮保持不可用、无法二次提交；列表刷新完成后才恢复可用。
861	test('提交等待及列表刷新完成前按钮不可用且不能二次提交，刷新完成后恢复', { timeout: 60000 }, async (t) => {
862	  const { page, baseURL } = await setupPage(t);
863	
864	  // 同时挂起第一次创建请求与创建后的列表查询；拦截在页面加载完成后才打开，
865	  // 因此打开页面的首次列表查询不受影响。
866	  await page.setRequestInterception(true);
867	  const posts = [];
868	  let markGetArrived;
869	  const getArrived = new Promise((resolve) => { markGetArrived = resolve; });
870	  let releaseGet;
871	  const getReleased = new Promise((resolve) => { releaseGet = resolve; });
872	  page.on('request', (req) => {
873	    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
874	      const entry = { body: req.postData() };
875	      posts.push(entry);
876	      entry.whenReleased = new Promise((resolve) => {
877	        entry.release = () => resolve();
878	      });
879	      entry.whenReleased.then(() => req.continue());
880	    } else if (req.method() === 'GET' && req.url().endsWith('/api/rooms')) {
881	      markGetArrived();
882	      getReleased.then(() => req.continue());
883	    } else {
884	      req.continue();
885	    }
886	  });
887	
888	  const createdPromise = nextPostResponse(page);
889	  await page.type('#name', '按钮禁用窗口的房间');
890	  await chooseGame(page, 'gomoku');
891	  await setTurnSeconds(page, '0');
892	  await page.click('#submit');
893	
894	  // POST 在途：按钮不可用，重复提交无效。
895	  await sleep(100);
896	  assert.equal(posts.length, 1, '应只发起一次创建请求');
897	  assert.equal((await readFormState(page)).submitDisabled, true);
898	  await tryDuplicateSubmit(page);
899	  assert.equal(posts.length, 1, '等待期间不得发出第二次创建请求');
900	
901	  // 创建结果返回、成功提示已显示，但列表刷新尚未完成：按钮仍不可用。
902	  posts[0].release();
903	  const created = await createdPromise;
904	  assert.equal(created.status, 201);
905	  await waitForMessageKind(page, 'ok');
906	  await getArrived;
907	  await sleep(300);
908	  assert.equal((await readFormState(page)).submitDisabled, true, '列表刷新完成前按钮应保持不可用');
909	  await tryDuplicateSubmit(page);
910	  assert.equal(posts.length, 1, '列表刷新期间重复提交也不得发起第二次请求');
911	
912	  // 列表查询仍挂起时不应渲染出第三行。
913	  assert.equal((await readRows(page)).length, 2, '挂起的列表刷新完成前不应展示新房间行');
914	
915	  // 放行列表刷新：新房间上屏后按钮恢复可用，表单按成功复位。
916	  releaseGet();
917	  await waitForRowCount(page, 3);
918	  await page.waitForFunction(
919	    () => !document.getElementById('submit').disabled,
920	    { timeout: 10000 },
921	  );
922	  assert.equal((await readFormState(page)).submitDisabled, false, '本次处理完成后按钮应恢复可用');
923	  assert.deepEqual(await readFormState(page), RESET_FORM);
924	  const serverRooms = await readServerRooms(baseURL);
925	  assert.equal(serverRooms.length, 3);
926	  assert.equal(serverRooms[2].id, created.body.id);
927	});
